{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Camellianin A, a flavonoid diglycoside, produced brain detection of its monoglucoside camellianin B after oral dosing in rats, directly showing that a flavonoid 7-O-glucoside can achieve CNS access; the query is the closely related luteolin 7-O-glucoside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Hydroxysafflor yellow A, a highly polar polyglycosylated polyphenol, reached 1026 ng/g in rat brain after systemic administration, demonstrating that extensive glycosylation and polarity do not preclude meaningful brain entry.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Danshensu, a polar catechol-containing acid, crosses the BBB despite being a P-gp efflux substrate; brain levels increased with verapamil, showing efflux liability alone does not mean inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Vidarabine (ara-A), a polar nucleoside, achieved a mean CSF/plasma ratio of 66% in humans, illustrating that transporter-mediated or active uptake can provide meaningful CNS exposure despite low passive permeability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted pass. The closest high-transfer analogue (camellianin B, a flavonoid 7-O-glucoside) is detected in brain after oral administration, and other polar glycosides/polyphenols show measurable CNS exposure despite efflux and poor passive properties; the physicochemical prior is overridden by direct experimental evidence.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for luteolin 7-O-glucoside itself.",
    "Relative contribution of deglycosylation to luteolin aglycone versus intact glucoside transport is unknown.",
    "Human CNS exposure data for this exact glycoside are absent.",
    "P-gp/BCRP efflux magnitude for the query is inferred, not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

